\begin{itemchoice}
			\itemch Ta có $90^\circ < \alpha < 180^\circ$ nên $\cos \alpha < 0$.
			\itemch Ta có $\cos \alpha = -\sqrt{1 - \sin^2 \alpha} = -\sqrt{1 - m^2}$. 
			\itemch Ta có $\sin(180^\circ - \alpha) = \sin \alpha = m$ (hai góc bù nhau).
			\itemch Biến đổi biểu thức vế trái:
			\begin{align*}
			VT &= \tan^2 \alpha (\sin^2 \alpha - 1) + \sin^2 \alpha - \sin \alpha \\
			&= \tan^2 \alpha \cdot (-\cos^2 \alpha) + \sin^2 \alpha - \sin \alpha \\
			&= -\sin^2 \alpha + \sin^2 \alpha - \sin \alpha \\
			&= -m
			\end{align*}
			Vì $-m \neq 1 - m$ nên đây là mệnh đề sai.
		\end{itemchoice}
